-- Echoes of the Abyss
INSERT INTO story
(story_id, release_date, release_status, story_title, story_description, user_id, created_time)
VALUES ('d30eb63f-655a-47db-ad8d-52d81a3e552f',
        '2025-04-12',
        true,
        'Echoes of the Abyss',
        'Professor Grimshaw arrives at Blackwood Manor to debunk its haunted myths. He encounters unwelcoming locals and discovers a strange, missing book in the library. Whispers and an ominous presence draw him to a forbidding door, suggesting the manor''s secrets are more terrifying than imagined.',
        '063666bd-6ecb-440d-b560-dc306493fe59',
        '2025-04-01 14:25:00.000000');

INSERT INTO chapter (chapter_id, chapter_number, chapter_title, story_id, chapter_content, created_time)
VALUES ('6f3b8e4d-9a1c-4e5f-8d2a-3b7c0e9f1a2b',
        1,
        'The Whispers of Blackwood Manor',
        'd30eb63f-655a-47db-ad8d-52d81a3e552f',
        '<p>The old Blackwood Manor loomed over the small town of Silent Hollow like a skeletal finger pointing accusingly at the sky. Locals whispered tales of its dark history, of a family consumed by madness and tragedy, of restless spirits that roamed its decaying halls. I, Professor Alistair Grimshaw, a man of science and skepticism, arrived in Silent Hollow with a singular purpose: to debunk the myths surrounding Blackwood Manor. I believed that every ghost story had a rational explanation, a trick of the light, a draft in the right place, a mind too willing to believe. My colleagues at the university thought I was chasing shadows, a fool''s errand, but I knew there was more to the manor than superstition.</p><p>The townsfolk were less than welcoming. Their eyes, filled with a mixture of fear and resentment, followed my every move. The air itself seemed heavy, pregnant with unspoken warnings. The only person who would speak to me with any semblance of civility was the old librarian, Mrs. Elmsworth. She had a kind face, etched with wrinkles that spoke of a long life spent among books, but even she couldn''t hide the apprehension in her voice when she spoke of the manor. "The Blackwoods were cursed," she''d said, her voice barely a whisper. "They delved into things they shouldn''t have, and the house... the house remembers." I thanked her for her time, dismissing her concerns as folklore, but a seed of doubt had been planted. As I stood before the imposing gates of Blackwood Manor, a chill, sharper than the autumn air, ran down my spine. The adventure, and perhaps the horror, had begun.</p>',
        '2025-04-01 14:25:00.000000'),

       ('a8d4c2e1-5b9f-4d3a-8c6e-0f2b7d1e9a3c',
        2,
        'Descent into Darkness',
        'd30eb63f-655a-47db-ad8d-52d81a3e552f',
        '<p>The gates of Blackwood Manor creaked open as if inviting me into its decaying embrace. The grounds were overgrown, a testament to years of neglect. Twisted branches clawed at the sky, and the air hung thick with the scent of damp earth and decay. The manor itself was a gothic monstrosity, its once-grand facade now crumbling, its windows like vacant eyes staring out into the desolate landscape. I pushed open the heavy oak door, the sound echoing through the silent halls like a mournful cry. Dust motes danced in the faint light filtering through the grimy windows, illuminating cobwebs that draped like ghostly shrouds over antique furniture.</p><p>I began my exploration in the grand library, its shelves lined with leather-bound books, many of them warped and rotting. I ran my gloved hand over the spines, feeling a strange energy emanating from them. One book, bound in black leather with no title, felt particularly... wrong. As I reached for it, a sudden gust of wind slammed the door shut, plunging the room into near darkness. My heart pounded in my chest. It was just the wind, I told myself, just a draft. But the silence that followed was more unsettling than any sound. I fumbled for my flashlight, its beam cutting through the oppressive gloom. When I finally dared to look back at the bookshelf, the black book was gone.</p>',
        '2025-04-01 14:27:00.000000'),

       ('3c7a0b9e-1d4f-4e8a-9b2c-6e5d3f0a8c1b',
        3,
        'The Hall of Whispers',
        'd30eb63f-655a-47db-ad8d-52d81a3e552f',
        '<p>The disappearance of the black book rattled me more than I cared to admit. I tried to focus on my investigation, meticulously examining each room, each artifact, searching for any clue that could explain the strange occurrences at Blackwood Manor. I found old journals filled with cryptic entries, strange symbols etched into the walls, and portraits of the Blackwood family, their eyes seeming to follow me as I moved. Each discovery only deepened the mystery, pulling me further into the manor''s dark embrace.</p><p>I eventually found myself in a long, narrow hallway. The air here was colder, heavier, than anywhere else in the house. A faint whispering seemed to emanate from the walls themselves, a chorus of voices just beyond the edge of hearing. I strained to understand the words, but they remained elusive, a jumble of syllables that sent shivers down my spine. As I walked further down the hall, the whispering grew louder, more insistent. I felt a presence, a sense of being watched, judged. The temperature plummeted, and my breath fogged in the air. At the end of the hall, a single door, ornately carved with grotesque figures, beckoned. Or perhaps, it threatened. I knew, with a certainty that defied logic, that whatever secrets Blackwood Manor held, they lay behind that door. My adventure was far from over; it felt like it had only just begun. The horror of what lay ahead was palpable.</p>',
        '2025-04-01 14:28:00.000000'),

       ('9e2f1d0a-4c8b-4a3e-8d6c-5b7a9f2e0c1d',
        4,
        'The Devil''s Door',
        'd30eb63f-655a-47db-ad8d-52d81a3e552f',
        '<p>The door at the end of the Hall of Whispers was cold to the touch, the grotesque figures seeming to writhe in the dim light. I hesitated, my hand hovering over the ornate handle. A sense of dread washed over me, a primal fear that whispered of unspeakable horrors. But my curiosity, my thirst for knowledge, outweighed my fear. I had come too far to turn back now. I took a deep breath, steeling my nerves, and turned the handle. The door creaked open, revealing a circular chamber bathed in an eerie green glow. In the center of the room, a pedestal held a large, pulsating crystal, its light casting grotesque shadows on the walls.</p><p>As I stepped into the chamber, the whispering intensified, coalescing into a single, malevolent voice that seemed to echo directly inside my mind. It spoke of ancient rituals, of forbidden knowledge, of a power that should never have been awakened. The room began to spin, the grotesque figures on the walls twisting and contorting into nightmarish shapes. I felt a searing pain in my head, as if my very thoughts were being invaded. I stumbled towards the pedestal, drawn by the crystal''s mesmerizing glow, even as the voice in my head screamed at me to turn back. I had to know the truth, no matter the cost.</p>',
        '2025-04-01 14:29:00.000000'),

       ('0b6e8c3a-2f9d-4b1e-8a5c-7d4f0e9a3b2c',
        5,
        'The Blackwood Legacy',
        'd30eb63f-655a-47db-ad8d-52d81a3e552f',
        '<p>As I reached the pedestal, the crystal pulsed with a blinding light, and the voice in my head reached a deafening crescendo. Images flooded my mind: the Blackwood family, generations ago, performing dark rituals in this very chamber; a pact made with an ancient entity; the source of the curse that had plagued the manor for centuries. The black book, I realized, was a key, a conduit to this power. And the entity... it was still here, dormant but waiting. The whispering wasn''t the house; it was it.</p><p>The crystal''s light subsided, and I found myself kneeling before the pedestal, the chamber silent once more. But the silence was more terrifying than the whispers. I knew the truth now, the horrifying legacy of the Blackwood family. The madness, the tragedy, it was all a result of their thirst for forbidden knowledge, their willingness to bargain with forces beyond their comprehension. And now, I was caught in the middle of it, the entity''s attention turned towards me. I had to find a way to contain it, to sever the connection, before it was unleashed upon the world.</p>',
        '2025-04-01 14:30:00.000000'),

       ('5a9f2e0d-8c4b-4d1a-9b7e-3f6c0a8d5e2b',
        6,
        'The Binding',
        'd30eb63f-655a-47db-ad8d-52d81a3e552f',
        '<p>I knew that to contain the entity, I had to find a way to reverse the ritual, to break the pact made by the Blackwoods. The answer, I believed, lay within the journals I had found, hidden within the cryptic symbols and diagrams. I spent what felt like an eternity deciphering the ancient texts, the manor itself seeming to resist my efforts. The temperature fluctuated wildly, objects moved on their own, and the whispering voice tried to deceive me with illusions and false promises.</p><p>Finally, I found it: a ritual of binding, a way to seal the entity back into its prison. But it required a sacrifice, a sacrifice of something precious. As I prepared the chamber, placing the artifacts I had found in their designated positions, I knew what I had to do. The entity had entered my mind, had seen my memories, my hopes, my fears. It knew what I held most dear. With a heavy heart, I placed Mrs. Elmsworth''s kind old librarian''s book, the only thing I had from her, on the pedestal. The crystal flared to life, and the entity screamed, its power surging through the chamber. I began the incantation, my voice trembling but firm, the ancient words echoing through the manor. The battle between my will and the entity''s raged, a psychic storm that threatened to tear me apart.</p>',
        '2025-04-01 14:31:00.000000'),

       ('8d3c6e1f-0a9b-4e2a-8c5d-7b4f9a0e3d1c',
        7,
        'The Eye of the Storm',
        'd30eb63f-655a-47db-ad8d-52d81a3e552f',
        '<p>The chamber became a vortex of energy, the crystal pulsing with raw power as the entity fought against the binding ritual. The grotesque figures on the walls seemed to melt and reform, their expressions shifting from rage to despair. I felt my own strength waning, the incantation faltering as the entity''s influence threatened to overwhelm me. My mind was a battlefield, memories and emotions clashing against the entity''s dark designs.</p><p>I saw Mrs. Elmsworth''s smiling face, her gentle encouragement, and the countless hours she had spent guiding my research. This fueled my resolve. I would not let her sacrifice be in vain. I focused my will, drawing upon a power I didn''t know I possessed, and the ancient words of the binding ritual flowed from my lips with renewed force. The crystal shuddered, and a beam of pure white light erupted from its core, piercing the darkness of the chamber.</p>',
        '2025-04-01 14:32:00.000000'),

       ('4b9e2c7a-0d3f-4e1b-8a6c-5f2d9b0e3c1a',
        8,
        'The Sealing',
        'd30eb63f-655a-47db-ad8d-52d81a3e552f',
        '<p>The white light intensified, pushing back against the entity''s chaotic energy. I could feel the entity weakening, its hold on the manor loosening. The whispering voice, once a deafening roar, was reduced to a whimper, then silence. The grotesque figures on the walls froze, their twisted forms becoming mere carvings once more. The crystal, its light now a steady, calming glow, began to descend back into its pedestal.</p><p>As the crystal settled, a sense of profound peace washed over the chamber. The oppressive atmosphere lifted, replaced by a stillness that was almost serene. I felt the entity''s presence receding, being drawn back into its ancient prison. The binding was working. The connection was being severed. But I knew it was not truly over. The entity was sealed, not destroyed. It would remain dormant, waiting for another opportunity, another unwitting soul to exploit its power.</p>',
        '2025-04-01 14:33:00.000000'),

       ('8f5a3d0e-1c9b-4a2e-8d7c-6b4f0a9e2d1b',
        9,
        'The Aftermath',
        'd30eb63f-655a-47db-ad8d-52d81a3e552f',
        '<p>The ordeal had left me drained, both physically and emotionally. I collapsed onto the cold stone floor, the silence of the chamber a stark contrast to the chaos that had just transpired. I had faced a horror beyond my comprehension, had delved into the darkness of Blackwood Manor, and had emerged... changed. The skepticism that had defined me was gone, replaced by a grudging respect for the unknown, for the forces that lay hidden beneath the surface of the world.</p><p>I spent the next few days recovering in Silent Hollow, the townsfolk now regarding me with a mixture of awe and gratitude. Mrs. Elmsworth''s sacrifice had not been in vain. I told them the manor''s secrets, the truth about the Blackwoods and the entity, hoping to dispel the myths and prevent anyone else from falling prey to its power. But I knew that some secrets were destined to endure, whispered in the shadows, waiting to be rediscovered.</p>',
        '2025-04-01 14:34:00.000000'),

       ('2a6d8e1c-9f0b-4c3a-8b5e-7d2f0c9a3e1d',
        10,
        'Echoes of the Abyss',
        'd30eb63f-655a-47db-ad8d-52d81a3e552f',
        '<p>Before leaving Silent Hollow, I visited Blackwood Manor one last time. The grounds were still overgrown, the manor still stood as a grim testament to the past, but the oppressive atmosphere was gone. The windows no longer seemed like vacant eyes, but rather like empty sockets, devoid of the malevolence that had once resided within. I walked through the silent halls, the echoes of the entity''s voice now just a faint memory.
</p><p>As I stood in the circular chamber, before the now-dormant crystal, I knew that I would never forget what had happened here. The adventure, the horror, it would forever be etched into my soul. I had peered into the abyss, had faced the darkness, and had survived. But I also knew that the abyss never truly closes. It waits, and it whispers, and it echoes in the hearts of those who dare to listen. And I knew, with a chilling certainty, that my journey was far from over. The echoes of Blackwood Manor, the echoes of the entity, would follow me, always.</p>',
        '2025-04-01 14:35:00.000000');


-- Heartbreak High
INSERT INTO story
(story_id, release_status, story_title, story_description, user_id, created_time)
VALUES ('a7b8c9d0-e1f2-3456-7890-abcdef123456',
        true,
        'Heartbreak High',
        'Skylar, a new transfer student at Northwood High, finds herself navigating the complexities of teenage social dynamics. She befriends Maya and Liam, and is assigned to work on a project with the intriguing loner, Damien. As they collaborate, Skylar finds herself drawn to Damien''s intelligence and mysterious nature.',
        '3df592a4-daa8-4819-863e-d4f7998ad0f3',
        '2025-04-02 12:01:00.000000');

-- Chapter 1
INSERT INTO chapter (chapter_id, chapter_number, chapter_title, story_id, chapter_content, created_time)
VALUES ('8f9e0d1c-2b3a-4567-89ab-cdef01234567',
        1,
        'The New Girl',
        'a7b8c9d0-e1f2-3456-7890-abcdef123456',
        '<p>The fluorescent lights of Northwood High buzzed overhead, casting an unflattering glow on the crowded hallway. I clutched my schedule, the paper crinkling in my sweaty hand. <span style="font-size: 16px;">Transferring schools mid-year was my worst nightmare. 😓</span> Everyone else seemed to know where they were going, who their friends were, and what their deal was. Me? I was just trying to find room 304 without tripping over a rogue backpack or making eye contact with anyone.</p>

        <p>I finally spotted the room number and slipped inside, grateful to be out of the chaos. The classroom was already mostly full, and all eyes turned to me as I entered. A few whispers rippled through the air, and I felt my cheeks burning. The teacher, a kind-faced woman with a warm smile, gestured to an empty desk in the back. <strong>“Welcome, you must be...?”</strong></p>

        <p>“Skylar Evans,” I mumbled, making my way to the desk as quickly as possible.</p>

        <p>The boy sitting next to me had dark, brooding eyes and a jawline that could cut glass. He wasn’t paying attention to me, though, his gaze fixed on something outside the window. I couldn’t help but steal a few glances at him throughout the class. There was an air of mystery about him that I found strangely <span style="color: #9b59b6;">attractive.</span> His name, I later learned from the attendance sheet, was Damien. 😏</p>',
        '2025-04-02 12:01:00.000000');

-- Chapter 2
INSERT INTO chapter (chapter_id, chapter_number, chapter_title, story_id, chapter_content, created_time)
VALUES ('7d6e5f4a-3b2c-4567-89ab-cdef01234567',
        2,
        'Unexpected Friendships',
        'a7b8c9d0-e1f2-3456-7890-abcdef123456',
        '<p>Lunchtime was even more daunting than homeroom. The cafeteria was a sea of cliques: the jocks, the cheerleaders, the theater kids, the... well, I wasn’t sure where I fit in yet. I grabbed a tray and some mystery meat 🍖, then scanned the room for an empty table. Just as I was about to resign myself to eating alone in the bathroom, a girl with bright pink hair 🌸 and a mischievous grin waved me over.</p>

        <p>“Hey, you’re the new girl, right? I’m Maya,” she said, gesturing to the two empty seats at her table. “And this is Liam,” she added, nodding to a guy with kind eyes and a surprisingly witty sense of humor.</p>

        <p>I hesitantly joined them, relieved to have found some friendly faces. Maya was a whirlwind of energy ⚡, passionate about everything from social justice to obscure indie bands. Liam was more laid-back but always ready with a sarcastic quip or a supportive word. They were an unlikely pair, but they were fiercely loyal to each other, and they welcomed me into their circle without hesitation.</p>

        <p>As we talked, I noticed Damien sitting alone at a table across the cafeteria, still lost in his thoughts. I wondered what his story was. 🤔</p>',
        '2025-04-02 12:03:00.000000');

-- Chapter 3
INSERT INTO chapter (chapter_id, chapter_number, chapter_title, story_id, chapter_content, created_time)
VALUES ('0c6c52e5-fc81-435f-9ddd-5071db3a7fa9',
        3,
        'The Project',
        'a7b8c9d0-e1f2-3456-7890-abcdef123456',
        '<p>Mr. Harrison, our English teacher, assigned a group project: a modern retelling of a classic novel.</p>

        <p>I was paired with Maya and Liam, which I was thrilled about. But then Mr. Harrison dropped a bombshell: he was assigning one extra student to each group, someone who needed a little “extra credit.” That someone turned out to be Damien.</p>

        <p>My heart did a weird little flutter-kick when Mr. Harrison announced it. I tried to play it cool 😎, but I could feel Maya’s knowing smirk boring into me. Liam, ever the observant one, raised an eyebrow but didn’t say anything.</p>

        <p>Damien didn’t seem particularly thrilled about the project, or about working with us. He was quiet and withdrawn during our first meeting, offering only a few terse suggestions. But as we started brainstorming 💭, his passion for literature became apparent. He had a unique perspective, a way of seeing things that added depth and complexity to our ideas. I found myself drawn to his intelligence and his quiet intensity. 😌</p>

        <p>Working together, we started to find a rhythm. Maya’s creativity, Liam’s humor, and Damien’s insightful analysis meshed surprisingly well. I even found myself looking forward to our meetings, even if Damien and I mostly communicated through charged glances and awkward silences. 💬</p>',
        '2025-04-02 12:04:00.000000');


-- The Haunting of Hollow Creek
INSERT INTO story
(story_id, release_status, story_title, story_description, user_id, created_time)
VALUES ('e7c4f9a0-5d8f-4bdb-bce5-123456789abc',
        true,
        'The Haunting of Hollow Creek',
        'When a group of friends decides to spend the weekend at an old, abandoned mansion in Hollow Creek, they unwittingly awaken the dark spirits that haunt the place. As the days go by, they begin to experience strange occurrences — whispers in the dark, unsettling visions, and a growing sense of paranoia. One by one, they fall victim to the malevolent force lurking in the shadows, and soon, they realize they might not all make it out alive.',
        '3df592a4-daa8-4819-863e-d4f7998ad0f3',
        '2025-04-02 16:01:00.000000');

-- Insert chapters for the horror story
-- Chapter 1
INSERT INTO chapter (chapter_id, chapter_number, chapter_title, story_id, chapter_content, created_time)
VALUES ('f5a4b9d2-ec14-46fc-b678-99fbb1b3eab7',
        1,
        'Arrival at Hollow Creek',
        'e7c4f9a0-5d8f-4bdb-bce5-123456789abc',
        '<p>The van rumbled over the gravel road as we neared the mansion. The air grew heavier, and the trees surrounding the estate seemed to close in on us, their twisted branches like fingers reaching for the sky. As we pulled up, the mansion loomed in front of us — dark, foreboding, and strangely silent. I could feel a shiver run down my spine. 😨</p>
        <p>"Well, this is it," Mark said, looking at the mansion with a grin. "Let’s make it a weekend to remember." But something in the back of my mind told me this was a mistake. I had no idea just how right I was. 🏚️</p>',
        '2025-04-02 16:02:00.000000');

-- Chapter 2
INSERT INTO chapter (chapter_id, chapter_number, chapter_title, story_id, chapter_content, created_time)
VALUES ('f9a1c2d3-d2c9-4b6d-b94b-6ddef8ba1e50',
        2,
        'The Whispering Shadows',
        'e7c4f9a0-5d8f-4bdb-bce5-123456789abc',
        '<p>The first night was uneventful, or so we thought. But when the lights flickered and the house seemed to groan under some unseen weight, I couldn’t shake the feeling that something was watching us. Then, around midnight, I heard it. A whisper, soft at first, barely audible. It seemed to come from nowhere and everywhere at once. 👻</p>
        <p>"Who’s there?" I called out, but no one responded. I was about to shrug it off when I heard the voice again, this time clearer: "Get out." 😱</p>
        <p>I wasn’t sure if I had imagined it, but I couldn’t ignore the growing sense of dread that settled over the group. Something was wrong. Something was in this house with us.</p>',
        '2025-04-02 16:03:00.000000');

-- Chapter 3
INSERT INTO chapter (chapter_id, chapter_number, chapter_title, story_id, chapter_content, created_time)
VALUES ('d6f94d5e-33ed-42de-a2b7-c7ef7d3b5c41',
        3,
        'The Awakening',
        'e7c4f9a0-5d8f-4bdb-bce5-123456789abc',
        '<p>The next morning, things had gotten worse. One of our group members, Sarah, had gone missing. We searched the house, but there was no sign of her. The walls seemed to close in on us, the once grand mansion now a tomb of decay and shadows. That night, as we gathered around the fireplace, we heard a loud bang upstairs. 😨🔥</p>
        <p>We rushed to check, and what we found sent chills down my spine. The walls were covered in strange markings, and Sarah’s belongings were scattered across the floor, as if she had been dragged away in a hurry. 😵</p>
        <p>The whispers returned, louder now. "You shouldn’t have come," they hissed, the voices echoing in my mind. We were no longer alone in Hollow Creek. The house had awakened, and it had plans for us. 👹</p>',
        '2025-04-02 16:04:00.000000');

-- Insert the new story
INSERT INTO story
(story_id, release_status, story_title, story_description, user_id, created_time)
VALUES ('b8a1fbe3-2f92-4971-a097-bd01d42b9140',
        true,
        'Echoes of the Forgotten Forest',
        'A group of hikers venture into the mysterious Forgotten Forest, a place rumored to be cursed. As they make their way deeper into the woods, they start to experience strange phenomena — the trees seem to whisper their names, shadows follow them, and the air grows unnaturally cold. As night falls, they realize they are not alone. Something ancient and vengeful is hunting them, and they must find a way out before it’s too late.',
        '3df592a4-daa8-4819-863e-d4f7998ad0f3',
        '2025-04-02 17:00:00.000000');

-- The First Step
-- Chapter 1
INSERT INTO chapter (chapter_id, chapter_number, chapter_title, story_id, chapter_content, created_time)
VALUES ('a12d8c6f-37b0-43d5-9c6a-39a594d4b37b',
        1,
        'The First Step',
        'b8a1fbe3-2f92-4971-a097-bd01d42b9140',
        '<p>The sun was setting as we entered the forest. The trees, thick with age, seemed to stretch on forever. With every step, the feeling of being watched grew stronger. Our leader, Tom, reassured us that it was just the nature of the forest, but I couldn’t shake the feeling that something was wrong. The air was thick with silence, and the occasional rustle of leaves felt too deliberate. 🌲</p>
        <p>"I’m not sure about this," Sarah whispered, her voice shaking. "It feels like we’re being followed." 😟</p>',
        '2025-04-02 17:01:00.000000');

-- Chapter 2
INSERT INTO chapter (chapter_id, chapter_number, chapter_title, story_id, chapter_content, created_time)
VALUES ('c08c08f0-06c4-4ef6-b7d1-6a2d350f3b8a',
        2,
        'Whispers in the Dark',
        'b8a1fbe3-2f92-4971-a097-bd01d42b9140',
        '<p>Night had fallen, and we set up camp under the towering trees. The fire crackled in front of us, but there was an odd stillness in the air. That’s when we heard it — a whisper. Faint at first, but then clearer: "Leave." The voice was coming from everywhere and nowhere at once. 😱</p>
        <p>We all froze, eyes darting around the campfire. "Who’s playing a prank?" Tom asked, but no one answered. The whispering continued, growing louder. "Leave this place." It was as though the forest itself was speaking. 😳</p>',
        '2025-04-02 17:02:00.000000');

-- Chapter 3
INSERT INTO chapter (chapter_id, chapter_number, chapter_title, story_id, chapter_content, created_time)
VALUES ('b3f56d9c-05d1-44f3-81b3-c8a0625c0f79',
        3,
        'The Hunter in the Shadows',
        'b8a1fbe3-2f92-4971-a097-bd01d42b9140',
        '<p>The next morning, Sarah was gone. There were no signs of a struggle, just her backpack left behind near the campfire. Panic set in as we searched the surrounding area, but it was like she had vanished into thin air. We decided to leave, but as we tried to retrace our steps, we realized the forest had shifted. The path we had come down no longer existed. 😰</p>
        <p>Then we saw it — a figure moving in the shadows between the trees. It was tall, impossibly tall, and its movements were unnatural. "We have to run," Tom hissed, his face pale. But it was too late. The hunter was already closing in on us, its eyes glowing like embers in the darkness. 🔥</p>',
        '2025-04-02 17:03:00.000000');

-- The Colors of Us
INSERT INTO story
(story_id, release_status, story_title, story_description, user_id, created_time)
VALUES ('db14a441-e4b4-4d72-9c72-e9f23fae0c68',
        true,
        'The Colors of Us',
        'When two individuals from different worlds meet at a pride parade, they are drawn together by a deep, unspoken connection. One is a quiet artist, afraid to embrace their identity, while the other is an outspoken advocate, passionate about change. As they navigate their relationship, they face challenges from society and within themselves, learning what it truly means to love, accept, and be loved in return.',
        '3df592a4-daa8-4819-863e-d4f7998ad0f3',
        '2025-04-02 17:30:00.000000');

-- Insert chapters for the new LGBTQ+ love story
-- Chapter 1
INSERT INTO chapter (chapter_id, chapter_number, chapter_title, story_id, chapter_content, created_time)
VALUES ('dbd6b8fa-e8b0-4a88-b4ff-d12ec10fded7',
        1,
        'A Chance Encounter',
        'db14a441-e4b4-4d72-9c72-e9f23fae0c68',
        '<p>The streets were alive with vibrant colors as the pride parade marched through the city. The air was electric with joy and love, but I felt out of place. As an artist, I often stayed in the background, watching the world unfold through the lens of my sketches. But that day, something felt different. I was drawn to the loud, passionate voices that filled the air.</p>
        <p>And that’s when I saw her — standing tall, her rainbow flag draped over her shoulders, her eyes gleaming with purpose. There was something in her gaze, something that made my heart skip a beat. Our eyes met, and I could feel the electricity between us, like we were the only two people in the crowd. I tried to look away, but she smiled, and I couldn’t help but smile back. 🌈</p>',
        '2025-04-02 17:31:00.000000');

-- Chapter 2
INSERT INTO chapter (chapter_id, chapter_number, chapter_title, story_id, chapter_content, created_time)
VALUES ('4e35b332-c923-4027-a582-073df31f3ec1',
        2,
        'Unspoken Words',
        'db14a441-e4b4-4d72-9c72-e9f23fae0c68',
        '<p>We spent the next few days texting back and forth, sharing our thoughts and dreams. I could feel myself opening up to her in a way I had never done with anyone. Her name was Maya, and she was everything I admired — fearless, kind, and unapologetically herself. But as we talked, I could feel the weight of my own fears creeping in. I wasn’t ready to be fully open about who I was.</p>
        <p>"Why don’t you come to the gallery opening tonight?" Maya asked one evening. "You’ll love it, I promise." I hesitated, my heart pounding. Could I really step into that world? Could I be the person I was too afraid to show? 🌟</p>',
        '2025-04-02 17:32:00.000000');

-- Chapter 3
INSERT INTO chapter (chapter_id, chapter_number, chapter_title, story_id, chapter_content, created_time)
VALUES ('d074f508-c3d5-47cd-84e3-e7da3d29c95b',
        3,
        'A Leap of Faith',
        'db14a441-e4b4-4d72-9c72-e9f23fae0c68',
        '<p>The night of the gallery opening, I found myself standing in front of a mirror, my hands trembling as I adjusted my outfit. I had never felt more vulnerable. But Maya’s words echoed in my mind: "You are beautiful, exactly as you are." With that thought, I took a deep breath and left my apartment, walking into the unknown.</p>
        <p>When I arrived at the gallery, Maya was waiting for me. She beamed when she saw me, and I felt a warmth spread through me. "I’m so glad you came," she said, her hand brushing against mine. In that moment, everything felt right. Maybe, just maybe, I was ready to embrace who I was. 💖</p>',
        '2025-04-02 17:33:00.000000');


-- A Son of War
INSERT INTO story
(story_id, release_status, story_title, story_description, user_id, created_time)
VALUES ('2f93538f-0f99-45ff-a9f6-4b8f6369380e',
        true,
        'A Son of War',
        'Born amidst the chaos of the Vietnam War, a boy struggles with the stigma of being the son of an American soldier and a poor Vietnamese villager. Abandoned by his mother and rejected by society because of his mixed blood, he dreams of becoming a doctor, determined to prove to the world that he is more than the circumstances of his birth. Despite the hardships, he fights against the prejudice surrounding him, aiming to change the way people see him and build a better future for himself and his people.',
        '3df592a4-daa8-4819-863e-d4f7998ad0f3',
        '2025-04-02 18:00:00.000000');

-- Insert chapters for the new story
-- Chapter 1
INSERT INTO chapter (chapter_id, chapter_number, chapter_title, story_id, chapter_content, created_time)
VALUES ('42b5bdb4-6e2a-4671-a703-98428a622a57',
        1,
        'The Birth of a Child in the Shadows of War',
        '2f93538f-0f99-45ff-a9f6-4b8f6369380e',
        '<p>The war had torn everything apart — homes, families, lives. Amidst the devastation, I was born. My father, an American soldier, left before I could even remember his face. My mother, a poor Vietnamese villager, was left to raise me in a world that was hostile to us both. The villagers whispered behind her back, calling me the son of an enemy. To them, I was nothing more than a reminder of the violence that had ravaged their land. 🏚️</p>
        <p>My mother loved me, but the burden of her shame weighed heavily on her. One night, I woke to find her gone, leaving nothing but a note that told me to survive. I was left alone, abandoned by the only person who had ever cared for me. The villagers made it clear that I was unwanted. "Go back to where you came from," they would say, their words sharp and cruel. 🥀</p>',
        '2025-04-02 18:01:00.000000');

-- Chapter 2
INSERT INTO chapter (chapter_id, chapter_number, chapter_title, story_id, chapter_content, created_time)
VALUES ('a1c72ed1-f3fe-49c9-b4c5-d635d37de804',
        2,
        'An Unlikely Dream',
        '2f93538f-0f99-45ff-a9f6-4b8f6369380e',
        '<p>Despite the rejection, I never stopped dreaming. I wanted to be something more than the label they put on me. I wanted to prove that I wasn’t just the son of a war. I began studying whenever I could, reading whatever books I could find. The more I learned, the more I became determined. I would become a doctor, not only to heal the sick but to change the perception of who I was.</p>
        <p>The path wasn’t easy. I was a poor, half-blood child in a world that refused to accept me. But every time they called me names or mocked me, I told myself, "I will show them all." I would be a doctor, and they would see me as more than the son of a soldier. 🌱</p>',
        '2025-04-02 18:02:00.000000');

-- Chapter 3
INSERT INTO chapter (chapter_id, chapter_number, chapter_title, story_id, chapter_content, created_time)
VALUES ('d9ed6a1d-4c4b-44b5-b396-381e6b70b58d',
        3,
        'The Struggle and the Triumph',
        '2f93538f-0f99-45ff-a9f6-4b8f6369380e',
        '<p>Years passed, and the road to my dream was filled with hardship. I worked hard, often late into the night, studying medical books by the dim light of a candle. I was rejected by many schools, turned away because of my background. But I didn’t give up. I had to prove them wrong. The scars of my past, the prejudice I faced, they only fueled my fire. 🔥</p>
        <p>Finally, after years of struggle, I was accepted into medical school. It was a victory, not just for me but for every person who had ever been told they didn’t belong. I was going to become a doctor, and I was going to change the world — one patient, one heart, at a time.</p>',
        '2025-04-02 18:03:00.000000');

-- Insert the new story
INSERT INTO story
(story_id, release_status, story_title, story_description, user_id, created_time)
VALUES ('f5a5fe61-cc78-43fc-b8a0-4305d3fbb6ad',
        true,
        'The Echoes of War',
        'Haunted by the ghosts of those he killed in the Vietnam War, an American soldier struggles with the guilt that has plagued him for ten years. The spirits of the fallen soldiers and civilians follow him, demanding justice and revenge. As the years go by, he becomes determined not just to rid himself of the ghosts that haunt his soul, but to heal the wounds of the past between Vietnam and America. His mission becomes one of redemption — a journey of reconciliation between two nations scarred by war.',
        '3df592a4-daa8-4819-863e-d4f7998ad0f3',
        '2025-04-02 18:30:00.000000');

-- The Weight of Guilt
-- Chapter 1
INSERT INTO chapter (chapter_id, chapter_number, chapter_title, story_id, chapter_content, created_time)
VALUES ('b5fd8e77-c2d0-43de-bb78-6c1a1cfcde5e',
        1,
        'The Weight of Guilt',
        'f5a5fe61-cc78-43fc-b8a0-4305d3fbb6ad',
        '<p>It was the middle of the night when the whispers started again. At first, it was just a faint murmur, barely audible, like a distant memory tugging at the edges of my mind. But then it grew louder — the voices of the men, women, and children I had killed in Vietnam. The faces I couldn’t forget, their eyes filled with rage and sorrow, were everywhere I looked. 🖤</p>
        <p>Ten years had passed since the war ended, but the ghosts had never left me. Every night, I would relive those moments, hear the screams of my victims as if they were happening all over again. I had thought I could escape it — leave the war behind when I returned home. But the war was never truly over for me. It had followed me like a shadow, and I couldn’t outrun it.</p>',
        '2025-04-02 18:31:00.000000');

-- Chapter 2
INSERT INTO chapter (chapter_id, chapter_number, chapter_title, story_id, chapter_content, created_time)
VALUES ('bc9c028f-cf7d-4b36-bf57-ef35c1efab62',
        2,
        'The Battle Within',
        'f5a5fe61-cc78-43fc-b8a0-4305d3fbb6ad',
        '<p>Each night, the ghosts grew more insistent. The visions became clearer, their faces more defined. I could hear their names, feel their anger, their sorrow. "You killed me," they whispered, "Now, you must make it right." I didn’t know how to fix what I had done. I had tried to bury the past, to push it all down, but it always came back to haunt me. Every step I took felt like I was walking through the battlefield once again.</p>
        <p>But then, a thought struck me — what if I could do something to make up for my actions? What if I could help heal the wounds of war, not just for me but for both the Vietnamese people and my fellow Americans? Maybe, just maybe, that was the redemption I had been searching for. 🕊️</p>',
        '2025-04-02 18:32:00.000000');

-- Chapter 3
INSERT INTO chapter (chapter_id, chapter_number, chapter_title, story_id, chapter_content, created_time)
VALUES ('0ef4c214-f71d-4428-8c1a-61d636a83b4f',
        3,
        'A New Mission',
        'f5a5fe61-cc78-43fc-b8a0-4305d3fbb6ad',
        '<p>Determined to make amends, I began working on a mission of reconciliation. I reached out to Vietnam, seeking ways to help rebuild what had been destroyed — not just the buildings, but the hearts and minds of those affected by the war. I started by sponsoring medical missions, providing aid to villages that had suffered from the war’s devastation. Slowly, the ghosts seemed to quiet. But I knew I hadn’t yet earned their forgiveness.</p>
        <p>As I spent more time in Vietnam, I began to understand their pain, their distrust. The wounds of war ran deep on both sides. I could never undo the horrors I had participated in, but I could help bring two nations together — a mission not of battle, but of peace. And perhaps, in doing so, I would finally find the peace I had been seeking for so long. 🇻🇳🇺🇸</p>',
        '2025-04-02 18:33:00.000000');

-- The Grand Adventure of Clutch the Cockroach
INSERT INTO story
(story_id, release_status, story_title, story_description, user_id, created_time)
VALUES ('c1b05e6d-6c96-4744-92ca-65ac0409250d',
        true,
        'The Grand Adventure of Clutch the Cockroach',
        'Clutch the cockroach has always dreamed of more than scurrying around in the dark corners of the kitchen. One night, an unexpected turn of events leads him on a grand adventure beyond the confines of the house. From evading traps to discovering the hidden wonders of the outside world, Clutch learns about bravery, survival, and the unexpected friendships found in the most unlikely places.',
        '3df592a4-daa8-4819-863e-d4f7998ad0f3',
        '2025-04-02 19:00:00.000000');

-- Insert chapters for the new story
-- Chapter 1
INSERT INTO chapter (chapter_id, chapter_number, chapter_title, story_id, chapter_content, created_time)
VALUES ('f6b9e80e-7f42-41c7-8b12-689332c3270d',
        1,
        'The Great Escape',
        'c1b05e6d-6c96-4744-92ca-65ac0409250d',
        '<p>Clutch had always known the kitchen as his kingdom — the dimly lit corners, the towering cabinets, and the scraps of food that fell to the floor. But lately, he had begun to grow restless. There had to be more to life than scuttling around in the shadows, avoiding the broom and dodging the sticky traps. He had heard whispers from the other cockroaches about the outside world, a place of vast horizons and endless possibilities. And tonight, he decided, he would find out for himself.</p>
        <p>As he squeezed through a crack in the door, Clutch felt the cool night air for the first time. It smelled fresh, like freedom. His tiny legs wobbled with excitement. Little did he know, this was just the beginning of his grand adventure.</p>',
        '2025-04-02 19:01:00.000000');

-- Chapter 2
INSERT INTO chapter (chapter_id, chapter_number, chapter_title, story_id, chapter_content, created_time)
VALUES ('a4b47836-f18f-47fc-91ac-f9e387b4c3bc',
        2,
        'The Forest Beyond the Walls',
        'c1b05e6d-6c96-4744-92ca-65ac0409250d',
        '<p>Clutch found himself in a vast garden, the leaves of plants towering over him like giants. It was overwhelming at first, with strange sounds and creatures he had never seen before. He narrowly escaped being squashed by a curious frog and had to dodge a swarm of ants on a mission to gather food. The forest beyond the walls was dangerous, but also exhilarating. Every nook and cranny seemed to hold new mysteries, and Clutch couldn’t help but be excited by the unknown.</p>
        <p>But it wasn’t all peril. He discovered the wonders of the world outside the kitchen — the sweet scent of flowers, the rush of wind through the trees, and the sparkling dew on the grass in the early morning. There was so much more to life than he had ever imagined. And yet, his adventure was far from over.</p>',
        '2025-04-02 19:02:00.000000');

-- Chapter 3
INSERT INTO chapter (chapter_id, chapter_number, chapter_title, story_id, chapter_content, created_time)
VALUES ('e9b0b6fe-6184-4451-b6f1-b7da56a855a3',
        3,
        'An Unexpected Ally',
        'c1b05e6d-6c96-4744-92ca-65ac0409250d',
        '<p>As Clutch journeyed deeper into the unknown, he came across a creature he had never seen before. It was a bright yellow caterpillar, plodding along slowly, its tiny legs moving with determination. At first, Clutch was wary — after all, most creatures in the garden seemed dangerous. But to his surprise, the caterpillar spoke.</p>
        <p>"Where are you heading, little roach?" the caterpillar asked, its voice kind but curious.</p>
        <p>"I’m not sure," Clutch replied. "I’m on an adventure. I want to see what lies beyond the kitchen." </p>
        <p>The caterpillar smiled. "You’re brave, I can see that. The world is vast and full of wonders, but also dangers. If you stick with me, I can show you some of the safest paths." Clutch hesitated but then realized he could use a guide. And so, the unlikely duo continued their journey together, forming a friendship that would help them overcome even the most dangerous obstacles ahead.</p>',
        '2025-04-02 19:03:00.000000');

